/* Offline cache for the RAS drill site.  Generated by build.py — edit sw_template.js.

   The page is one 3.5 MB file, so downloading it on every visit would be slow and
   expensive on mobile data. It is cached on the first visit and served from the
   phone after that. VER changes on every build, which is what evicts the old copy:
   the new worker installs in the background and takes over on the next launch. */
const VER = "ras-c0cf4bb58cc4";
const SHELL = ["./", "./index.html", "./manifest.webmanifest", "./icon.svg",
               "./icon-192.png", "./icon-512.png", "./apple-touch-icon.png"];

self.addEventListener("install", e => {
  e.waitUntil(
    caches.open(VER)
      // one missing file must not fail the whole install, so each is added on its own
      .then(c => Promise.all(SHELL.map(u => c.add(u).catch(() => {}))))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener("activate", e => {
  e.waitUntil(
    caches.keys()
      .then(keys => Promise.all(keys.filter(k => k !== VER).map(k => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener("fetch", e => {
  const req = e.request;
  if (req.method !== "GET") return;

  const url = new URL(req.url);

  // The PDFs are ~34 MB in total. Storing them silently would be a rude use of the
  // phone's disk, so they always go straight to the network and are never cached.
  if (url.pathname.endsWith(".pdf")) return;

  if (req.mode === "navigate") {
    // Opening a PDF in a new tab is ALSO a navigation. Only the app document itself
    // may be written to the shell cache, or a PDF would overwrite the cached page.
    const isApp = url.origin === location.origin &&
                  (url.pathname.endsWith("/") || url.pathname.endsWith("/index.html"));
    if (!isApp) return;
    e.respondWith(
      fetch(req)
        .then(res => {
          if (res && res.ok) {
            const copy = res.clone();
            caches.open(VER).then(c => c.put("./index.html", copy)).catch(() => {});
          }
          return res;
        })
        // a navigation must never dead-end, so offline falls back to the cached page
        .catch(() => caches.match("./index.html").then(r => r || caches.match("./")))
    );
    return;
  }

  // Everything else — the icons, and the Google Fonts stylesheet and font files —
  // is immutable enough to serve from cache first and refresh in the background.
  e.respondWith(
    caches.match(req).then(hit => {
      const net = fetch(req).then(res => {
        if (res && (res.ok || res.type === "opaque")) {
          const copy = res.clone();
          caches.open(VER).then(c => c.put(req, copy)).catch(() => {});
        }
        return res;
      }).catch(() => hit);
      return hit || net;
    })
  );
});
